191	/** Saves the text as a file through the browser. */
192	function download(text: string, filename: string): void {
193	  const url = URL.createObjectURL(new Blob([text], { type: 'text/csv;charset=utf-8' }));
194	  const link = document.createElement('a');
195	  link.href = url;
196	  link.download = filename;
197	  link.click();
198	  setTimeout(() => URL.revokeObjectURL(url));
199	}
